  /// reset / closed sockets. Hard refusals (rate limit, 429, content
  /// filter, auth) fail fast.
  static final _transient = RegExp(
    '(?:5\\d\\d|connection\\s+(?:closed|reset|aborted|refused)|'
    'socket\\s+exception|stream\\s+closed)',
    caseSensitive: false,
  );

