        hiddenRecords: smolOk.hiddenRecords,
        summarizedMessages: smolOk.summarizedMessages,
      );
    }
    final mainOk = await _attempt(
      'main=$mainLabel',
      summarize: mainSummary,
      pass: pass,
      clock: clock,
